<script setup lang="ts">
import { money, summary, today, dateLabel } from '../../shared/domain'
const { invoices, load } = useInvoiceData(); const error = ref(''); const loading = ref(true)
const totals = computed(() => summary(invoices.value)); const pending = computed(() => invoices.value.filter(i => !i.reviewed && !i.archived))
async function refresh() { loading.value = true; error.value = ''; try { await load() } catch (e: any) { error.value = e.message } finally { loading.value = false } }
onMounted(refresh)
</script>
<template><div class="page-heading"><div><p class="eyebrow">{{ dateLabel(today()) }} · YOUR WORKSPACE</p><h1>A clearer view of your bills.</h1><p>Know what’s outstanding and what needs your attention.</p></div><NuxtLink to="/upload" class="button">Upload invoice ↑</NuxtLink></div><p v-if="error" class="error" role="alert">{{ error }} <button class="text-link" @click="refresh">Try again</button></p><p v-if="loading" class="loading" role="status">Loading your records…</p><template v-else><section class="stats" aria-label="Invoice summary"><article class="stat"><span>Total outstanding</span><strong>{{ money(totals.outstanding) }}</strong><small>Confirmed, unpaid invoices</small></article><article class="stat"><span>Overdue amount</span><strong class="danger-text">{{ money(totals.overdue) }}</strong><small>Unpaid and past their due date</small></article><article class="stat"><span>Due in the next 7 days</span><strong>{{ totals.dueSoon }} <em>invoices</em></strong><small>Including invoices due today</small></article></section><section v-if="pending.length" class="review-callout"><div class="callout-icon" aria-hidden="true">▤</div><div><p class="eyebrow">REVIEW BEFORE YOU RELY ON IT</p><h2>{{ pending.length }} invoice{{ pending.length === 1 ? '' : 's' }} to check.</h2><p>Unreviewed bills are excluded from your financial totals.</p></div><NuxtLink :to="`/invoices/${pending[0]!.id}`" class="button">Review next →</NuxtLink></section><section v-else-if="!invoices.length" class="review-callout"><div><p class="eyebrow">START WITH ONE BILL</p><h2>Your workspace is ready.</h2><p>Upload a PDF or photo, review its details, and keep track of payment.</p></div><NuxtLink to="/upload" class="button">Add your first invoice →</NuxtLink></section><div class="insights-grid"><section class="panel"><div class="section-heading"><h2>This month’s recorded bills</h2><span class="muted">By invoice date</span></div><div class="insight-body"><strong>{{ money(totals.monthlyTotal) }}</strong><p>{{ totals.monthlyCount }} confirmed invoices · {{ money(totals.monthlyTax) }} recorded GST</p><p class="muted">Invoice amounts, not cash spending or a GST filing calculation.</p></div></section><section class="panel"><div class="section-heading"><h2>Top suppliers this month</h2></div><div class="insight-body"><p v-if="!totals.topVendors.length" class="muted">Confirm an invoice to see supplier totals.</p><div v-for="[vendor, amount] in totals.topVendors" :key="vendor" class="vendor-row"><span>{{ vendor }}</span><strong>{{ money(amount) }}</strong></div></div></section></div><section class="panel"><div class="section-heading"><h2>Recent invoices</h2><NuxtLink to="/invoices" class="text-link">View all →</NuxtLink></div><InvoiceTable :invoices="invoices.filter(i => !i.archived).slice(0, 5)" /></section></template><p class="footnote">Dates use India Standard Time. Amounts are in INR.</p></template>
